  "inlineSchema": "datasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\ngenerator client {\n  provider      = \"prisma-client-js\"\n  output        = \"../src/generated/client\"\n  binaryTargets = [\"native\", \"rhel-openssl-1.0.x\", \"rhel-openssl-1.1.x\", \"rhel-openssl-3.0.x\", \"debian-openssl-1.1.x\", \"debian-openssl-3.0.x\"]\n}\n\ngenerator clientNodeModules {\n  provider      = \"prisma-client-js\"\n  binaryTargets = [\"native\", \"rhel-openssl-1.0.x\", \"rhel-openssl-1.1.x\", \"rhel-openssl-3.0.x\", \"debian-openssl-1.1.x\", \"debian-openssl-3.0.x\"]\n}\n\nmodel User {\n  id        String   @id @default(uuid())\n  name      String\n  email     String   @unique\n  password  String\n  role      String   @default(\"ADMIN\") // ADMIN, STAFF\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel Category {\n  id          String    @id @default(uuid())\n  name        String    @unique\n  slug        String    @unique\n  description String?\n  image       String?\n  products    Product[]\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n}\n\nmodel Product {\n  id                String         @id @default(uuid())\n  name              String\n  slug              String         @unique\n  description       String\n  shortDescription  String?\n  price             Float? // null means \"Contact for Price\"\n  priceType         String         @default(\"FIXED\") // FIXED, STARTING_FROM, CONTACT_FOR_PRICE\n  isContactForPrice Boolean        @default(false)\n  availability      String         @default(\"AVAILABLE\") // AVAILABLE, OUT_OF_STOCK, HIDDEN\n  isFeatured        Boolean        @default(false)\n  isPublished       Boolean        @default(true)\n  image             String\n  imagePublicId     String?\n  images            ProductImage[]\n  subcategory       String?\n  flowerType        String? // e.g. Rose + Mogra\n  length            String? // e.g. 90 cm\n  width             String?\n  height            String?\n  weight            String?\n  color             String? // e.g. Red + White, Yellow\n  suitableFor       String? // e.g. Wedding / Varmala / Puja\n  whatsappMessage   String?\n  categoryId        String\n  category          Category       @relation(fields: [categoryId], references: [id], onDelete: Cascade)\n  createdAt         DateTime       @default(now())\n  updatedAt         DateTime       @updatedAt\n\n  @@index([categoryId])\n  @@index([availability])\n  @@index([isFeatured])\n  @@index([isPublished])\n}\n\nmodel ProductImage {\n  id        String   @id @default(uuid())\n  url       String\n  publicId  String?\n  isPrimary Boolean  @default(false)\n  productId String\n  product   Product  @relation(fields: [productId], references: [id], onDelete: Cascade)\n  createdAt DateTime @default(now())\n\n  @@index([productId])\n}\n\nmodel Location {\n  id        String   @id @default(uuid())\n  district  String   @default(\"Nashik\")\n  taluka    String\n  village   String\n  area      String?\n  isActive  Boolean  @default(true)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([district])\n  @@index([taluka])\n  @@index([village])\n  @@index([isActive])\n}\n\nmodel Service {\n  id          String   @id @default(uuid())\n  title       String\n  slug        String   @unique\n  description String\n  highlight   String?\n  image       String\n  category    String   @default(\"Decoration\")\n  isAvailable Boolean  @default(true)\n  isFeatured  Boolean  @default(false)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n}\n\nmodel GalleryImage {\n  id            String   @id @default(uuid())\n  title         String\n  category      String // Wedding, Car, Haar & Mala, Bouquets, Events, Traditional, Stage, Mandap, Flowers\n  categoryName  String // e.g. Wedding Decorations\n  image         String\n  imagePublicId String?\n  description   String?\n  price         Float?\n  priceMode     String   @default(\"ENQUIRY_ONLY\") // FIXED, ENQUIRY_ONLY\n  isPublished   Boolean  @default(true)\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n}\n\nmodel Booking {\n  id            String   @id @default(uuid())\n  customerName  String\n  customerPhone String\n  eventType     String\n  eventDate     DateTime\n  eventLocation String\n  district      String?  @default(\"Nashik\")\n  taluka        String?\n  village       String?\n  serviceId     String?\n  productId     String?\n  productName   String?\n  budget        String?\n  message       String?\n  status        String   @default(\"NEW\") // NEW, CONTACTED, CONFIRMED, COMPLETED, CANCELLED\n  isDateBlocked Boolean  @default(false)\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n}\n\nmodel Enquiry {\n  id            String   @id @default(uuid())\n  customerName  String\n  customerPhone String\n  eventType     String?\n  eventDate     String?\n  eventLocation String?\n  district      String?  @default(\"Nashik\")\n  taluka        String?\n  village       String?\n  service       String?\n  productId     String?\n  productName   String?\n  budget        String?\n  message       String?\n  status        String   @default(\"NEW\") // NEW, CONTACTED, CONFIRMED, COMPLETED, CANCELLED\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n}\n\nmodel Review {\n  id           String   @id @default(uuid())\n  customerName String\n  rating       Int      @default(5)\n  comment      String\n  isApproved   Boolean  @default(false)\n  status       String   @default(\"PENDING\") // PENDING, APPROVED, REJECTED\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n}\n\nmodel Offer {\n  id          String    @id @default(uuid())\n  title       String\n  description String\n  image       String?\n  startDate   DateTime?\n  endDate     DateTime?\n  isActive    Boolean   @default(true)\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n}\n\nmodel BusinessSetting {\n  id          String   @id @default(uuid())\n  key         String   @unique\n  value       String\n  description String?\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n}\n\nmodel CarDecorationPost {\n  id            String   @id @default(uuid())\n  title         String\n  description   String?\n  price         Float?\n  priceText     String? // e.g. \"₹5,000\" or \"Price on Request\"\n  image         String\n  imagePublicId String?\n  status        String   @default(\"PUBLISHED\") // PUBLISHED, UNPUBLISHED\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  @@index([status])\n}\n",
